from collections import deque

class AhoCorasick:
    def __init__(self):
        self.trie = [{}]
        self.fail = [0]
        self.out = [[]]

    def insert(self, pattern: str, pattern_id: int):
        node = 0
        for ch in pattern:
            if ch not in self.trie[node]:
                self.trie[node][ch] = len(self.trie)
                self.trie.append({})
                self.fail.append(0)
                self.out.append([])
            node = self.trie[node][ch]
        self.out[node].append(pattern_id)

    def build(self):
        queue = deque()
        for ch, nxt in self.trie[0].items():
            queue.append(nxt)
        while queue:
            curr = queue.popleft()
            for ch, nxt in self.trie[curr].items():
                f = self.fail[curr]
                while f and ch not in self.trie[f]:
                    f = self.fail[f]
                self.fail[nxt] = self.trie[f].get(ch, 0)
                self.out[nxt].extend(self.out[self.fail[nxt]])
                queue.append(nxt)

    def search(self, text: str) -> list[tuple[int, int]]:
        node = 0
        res = []
        for i, ch in enumerate(text):
            while node and ch not in self.trie[node]:
                node = self.fail[node]
            node = self.trie[node].get(ch, 0)
            for pid in self.out[node]:
                res.append((i, pid))
        return res

