        Queue<Integer> q = new LinkedList<>();
        for (int nxt : trie.get(0).next.values()) q.add(nxt);
        while (!q.isEmpty()) {
            int curr = q.poll();
            for (var entry : trie.get(curr).next.entrySet()) {
                char c = entry.getKey(); int nxt = entry.getValue();
                int f = trie.get(curr).fail;
                while (f > 0 && !trie.get(f).next.containsKey(c)) f = trie.get(f).fail;
                trie.get(nxt).fail = trie.get(f).next.getOrDefault(c, 0);
                trie.get(nxt).out.addAll(trie.get(trie.get(nxt).fail).out);
                q.add(nxt);
            }
        }
    }
